import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { InstanceVisibility } from '/src/core/renderables/DetailedRingStreamingSystem/InstanceVisibility'
import { BoxGeometry, InstancedBufferAttribute, InstancedMesh, MeshBasicMaterial, Vector3 } from 'three'
import { state } from './profile.browser'
import { InstanceVisibility as Baseline } from './copy-runs-baseline-2026-10-26'

const stats = (values: number[]) => { const s = values.slice().sort((a,b)=>a-b); return { count:s.length,p50:s[15],p95:s[30],max:s[31] } }
export async function confirmCopyRuns(turn:number) {
  const c=getInitializedSimulationRuntime()!.container,engine:any=c.get(Tokens.Engine),camera=c.get(Tokens.Camera)
  const position=camera.position.clone(),orientation=camera.quaternion.clone(),proto:any=InstanceVisibility.prototype,original=proto.copyVisible,baseline=(Baseline.prototype as any).copyVisible
  const fixtures:any[]=[],ownedMeshes:InstancedMesh[]=[]
  engine.stop()
  try {
    camera.position.addScaledVector(new Vector3(1,0,0).applyQuaternion(orientation),turn/180)
    camera.rotateY(turn*Math.PI/180);camera.updateMatrixWorld(true)
    let calls=0,skipped=0
    proto.copyVisible=function(source:InstancedBufferAttribute,target:InstancedBufferAttribute,changed:boolean) {
      calls++
      const copying=changed||this.versions.get(source)!==source.version
      if(!copying||this.visibleCount===0){skipped++;return original.call(this,source,target,changed)}
      const sourceCopy=new InstancedBufferAttribute(source.array.slice(),source.itemSize,source.normalized,source.meshPerAttribute)
      const before=target.array.slice(),slots=this.slots.slice(0,this.visibleCount),count=this.visibleCount
      const result=original.call(this,source,target,changed)
      const name=source===this.matrix?'matrix':Array.from(this.attributes as Map<string,InstancedBufferAttribute>).find(([,attribute])=>attribute===source)?.[0]
      if(!name)throw Error('Unknown source attribute')
      fixtures.push({owner:this,name,source:sourceCopy,sourceSnapshot:sourceCopy.array.slice(),before,expected:target.array.slice(),slots,count,mesh:this.mesh.name})
      return result
    }
    engine.renderFrame();proto.copyVisible=original
    if(!fixtures.length)throw Error('No real changed copy operations captured')
    const snapshot=state()
    const owners=Array.from(new Set(fixtures.map(f=>f.owner))),contexts=new Map<any,any>()
    for(const owner of owners){
      const group=fixtures.filter(f=>f.owner===owner),pair:any={}
      for(const [key,Type]of [['baseline',Baseline],['optimized',InstanceVisibility]]as const){
        const mesh=new InstancedMesh(new BoxGeometry(1,1,1),new MeshBasicMaterial(),owner.matrix.count)
        ownedMeshes.push(mesh)
        mesh.instanceMatrix.array.set(owner.matrix.array)
        for(const[name,attribute]of owner.attributes as Map<string,InstancedBufferAttribute>)mesh.geometry.setAttribute(name,new InstancedBufferAttribute(attribute.array.slice(),attribute.itemSize,attribute.normalized,attribute.meshPerAttribute))
        const context:any=new Type(mesh)
        // Initialize the real class through its public path, then install captured slots.
        if(/AsteroidPool_L1/.test(owner.mesh.name))context.restore(0)
        else context.update(camera,0,0)
        context.slots.set(group[0].slots);context.visibleCount=group[0].count;mesh.count=group[0].count
        pair[key]={context,mesh}
      }
      contexts.set(owner,pair)
    }
    const copies=fixtures.map(f=>{
      const result:any={...f}
      for(const key of ['baseline','optimized']as const){
        const{context,mesh}=contexts.get(f.owner)[key]
        const source=f.name==='matrix'?context.matrix:context.attributes.get(f.name)
        const target=f.name==='matrix'?mesh.instanceMatrix:mesh.geometry.getAttribute(f.name)
        source.array.set(f.source.array);target.array.set(f.before)
        result[key]={context,source,target}
      }
      return result
    })
    const check=()=>{
      for(const f of copies)for(const key of ['baseline','optimized']as const){
        const{context,source,target}=f[key]
        ;(key==='baseline'?baseline:original).call(context,source,target,true)
        const actual=new Uint8Array(target.array.buffer),expected=new Uint8Array(f.expected.buffer)
        if(actual.length!==expected.length||actual.some((value,i)=>value!==expected[i]))throw Error('Captured copy differs: '+key+' '+f.mesh)
        if(JSON.stringify(target.updateRanges)!==JSON.stringify([{start:0,count:f.count*f.source.itemSize}]))throw Error('Upload range differs')
      }
    }
    check()
    const samples:{baseline:number[],optimized:number[]}={baseline:[],optimized:[]},repetitions=16
    const measure=(key:'baseline'|'optimized')=>{
      const copy=key==='baseline'?baseline:original,started=performance.now()
      for(let i=0;i<repetitions;i++)for(const f of copies){const{context,source,target}=f[key];copy.call(context,source,target,true)}
      return (performance.now()-started)/repetitions
    }
    for(let i=0;i<6;i++){measure('baseline');measure('optimized');await new Promise(r=>setTimeout(r,0))}
    for(let i=0;i<32;i++){
      for(const key of(i%2?['optimized','baseline']:['baseline','optimized'])as('baseline'|'optimized')[])samples[key].push(measure(key))
      await new Promise(r=>setTimeout(r,0))
    }
    check()
    for(const f of copies) {
      if(f.baseline.target.version!==f.optimized.target.version)throw Error("Version mismatch")
      for(const key of ['baseline','optimized']as const){
        const actual=new Uint8Array(f[key].source.array.buffer),expected=new Uint8Array(f.sourceSnapshot.buffer)
        if(actual.some((value,i)=>value!==expected[i]))throw Error("Source was mutated")
      }
    }
    return {turn,offsetUnits:turn/180,snapshot,calls,skipped,repetitions,receiver:'actual constructed class instances',instancePairs:owners.length,exactBytesAndRanges:true,sourceUnchanged:true,targetVersionsEqual:true,
      fixtures:copies.map(f=>{
        const runs:number[]=[];let start=0
        for(let i=1;i<=f.count;i++)if(i===f.count||f.slots[i]!==f.slots[i-1]+1){runs.push(i-start);start=i}
        return {mesh:f.mesh,itemSize:f.source.itemSize,type:f.source.array.constructor.name,count:f.count,capacity:f.source.count,bytes:f.count*f.source.itemSize*f.source.array.BYTES_PER_ELEMENT,runs:runs.length,bulkSlots:runs.filter(n=>n>=4).reduce((a,b)=>a+b,0),maxRun:Math.max(...runs)}
      }),samples,summary:{baseline:stats(samples.baseline),optimized:stats(samples.optimized)},
      caveat:'Captured changed nonempty copy calls from one real moving frame. Actual Baseline/Current class instances initialized through public paths, independent cloned sources/targets and captured slots. Full bytes including unused tail, upload ranges, source immutability and target versions match.32alternating pairs*16repeats,6warmup pairs. Frozen Git baseline59b35408 versus current full copyVisible method; changed=true forces copies, stable-input version skipping checked by unit tests. fixtures.bulkSlots is descriptive runs>=4slots, not implementation fast-path count. CPU copy only, no visibility/GPU/FPS claim.'}
  }finally{
    for(const mesh of ownedMeshes){mesh.dispose();mesh.geometry.dispose();(mesh.material as MeshBasicMaterial).dispose()}
    proto.copyVisible=original;camera.position.copy(position);camera.quaternion.copy(orientation);camera.updateMatrixWorld(true);engine.start()
  }
}

