import{createServer}from'vite'
import{chromium}from'@playwright/test'
import{writeFile}from'node:fs/promises'
Object.assign(process.env,{VITE_FS_DRIVER:'s3',VITE_S3_URL:'https://storage.yandexcloud.net',VITE_FILE_BUCKET:'textures',VITE_SHOW_STATS_PANEL:'false',VITE_SKY_SOURCE:'gaia'})
const output='benchmark-results/heavy-scenes/'+(process.env.REPORT_FILE||'copy-runs-production-2026-10-26.json')
const report={baselineCommit:'59b35408c127441387dd1cd3c66ac2b3b16ca962',startedAt:new Date().toISOString(),rows:[],errors:[],warnings:[],assetFailures:[],abortedRequests:[],outcome:'failed'}
let server,browser
try{
  server=await createServer({server:{host:'127.0.0.1',port:8094,strictPort:true,hmr:false}});await server.listen()
  browser=await chromium.launch({channel:'chrome',headless:true})
  const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1})
  page.on('pageerror',e=>report.errors.push(e.stack||e.message))
  page.on('console',m=>{if(m.type()==='error')report.errors.push(m.text());if(m.type()==='warning')report.warnings.push(m.text())})
  page.on('response',r=>{if(r.status()>=400)report.assetFailures.push(`${r.status()} ${r.url()}`)})
  page.on('requestfailed',r=>{const failure=`${r.failure()?.errorText} ${r.url()}`;if(/ERR_ABORTED/.test(r.failure()?.errorText??''))report.abortedRequests.push(failure);else report.assetFailures.push(failure)})
  await page.goto('http://127.0.0.1:8094/');await page.getByRole('button',{name:/^Run /}).first().waitFor()
  for(const[id,actor]of[[13,135],[12,127]]){
    console.log('Starting',id)
    await page.evaluate(async id=>Promise.race([(await import('/tests/browser/scenarioSoak.browser.ts')).selectScenario(id),new Promise((_,reject)=>setTimeout(()=>reject(Error('Startup timeout')),180000))]),id)
    for(const turn of [90,270]){
      await page.evaluate(async actor=>(await import('/benchmark-results/heavy-scenes/profile.browser.ts')).setView(actor,'belt'),actor)
      await page.waitForTimeout(5000)
      const result=await page.evaluate(async turn=>(await import('/benchmark-results/heavy-scenes/copy-runs-production-2026-10-26.browser.ts')).confirmCopyRuns(turn),turn)
      if(/SwiftShader|llvmpipe|software/i.test(result.snapshot.renderer))throw Error('Software renderer')
      report.rows.push({id,...result});await writeFile(output,JSON.stringify(report,null,2));console.log('COPY_CONFIRM',id,turn,JSON.stringify(result.summary))
    }
    await page.screenshot({path:output.replace(/\.json$/,'')+'-'+id+'.png'})
    await page.evaluate(async()=>(await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if(report.errors.length||report.warnings.length||report.assetFailures.length)throw Error('Browser/shader/asset issue')
  }
  const misses=report.rows.filter(r=>r.summary.optimized.p50/r.summary.baseline.p50>0.9)
  report.performanceGate={minimumMedianReduction:0.1,misses:misses.map(r=>({id:r.id,turn:r.turn,ratio:r.summary.optimized.p50/r.summary.baseline.p50}))}
  if(misses.length)throw Error('Copy runs performance gate: expected >=10% median reduction in every view')
  report.outcome='completed'
}catch(e){report.failure=e.stack||e.message;console.error(e);process.exitCode=1}
finally{report.finishedAt=new Date().toISOString();await writeFile(output,JSON.stringify(report,null,2));await browser?.close();await server?.close()}

