function cleanBrowser(run,expected){
  const badRequests=r=>r.diagnostics?.failedRequests.some(q=>!(r.title==='native texture fetch cancellation and cube orientation'&&/^http:\/\/127\.0\.0\.1:\d+\/held-texture\.png$/.test(q.url)&&q.failure==='net::ERR_ABORTED'))
